-- Reviewable starter catalog only. Nothing here is published as verified content.
begin;

on conflict(slug) do nothing;

select 'mpc','MPC',id,'Mathematics, physics and chemistry route example.' from public.education_levels where slug='intermediate'
on conflict(slug) do nothing;

on conflict(slug) do nothing;

select id,'cse','Computer Science and Engineering','Computing branch example.' from public.courses where slug='btech'
on conflict(course_id,slug) do nothing;

select id,'cybersecurity','Cybersecurity','Example area of study; not an official curriculum.' from public.branches where slug='cse'
on conflict(branch_id,slug) do nothing;

on conflict(slug) do nothing;

select c.id,s.id,s.slug in ('programming','mathematics','computer-systems')
from public.courses c cross join public.subjects s where c.slug='btech'
  and s.slug in ('programming','mathematics','computer-systems','networks','operating-systems','databases','web-foundations')
on conflict do nothing;

on conflict(slug) do nothing;

select target.id,prior.id from public.skills target cross join public.skills prior where
  (target.slug='linux-basics' and prior.slug='programming-fundamentals') or
  (target.slug='security-fundamentals' and prior.slug='networking-fundamentals') or
  (target.slug='web-security' and prior.slug='security-fundamentals') or
  (target.slug='cloud-security' and prior.slug='security-fundamentals')
on conflict do nothing;

values ('cybersecurity','Cybersecurity','Example learning pathway. Confirm education and opportunity details with official institutions and notifications.')
on conflict(slug) do nothing;

select cp.id,1,el.id,'Class 10','Explore available routes with your local board and institutions.' from public.career_paths cp cross join public.education_levels el where cp.slug='cybersecurity' and el.slug='class-10'
on conflict(career_path_id,sequence) do nothing;
select cp.id,2,s.id,'MPC','Example stream route; subject offerings differ between institutions.' from public.career_paths cp cross join public.streams s where cp.slug='cybersecurity' and s.slug='mpc'
on conflict(career_path_id,sequence) do nothing;
select cp.id,3,el.id,'Intermediate','Example progression stage.' from public.career_paths cp cross join public.education_levels el where cp.slug='cybersecurity' and el.slug='intermediate'
on conflict(career_path_id,sequence) do nothing;
select cp.id,4,c.id,'B.Tech','Example course; admission rules and duration vary by institution.' from public.career_paths cp cross join public.courses c where cp.slug='cybersecurity' and c.slug='btech'
on conflict(career_path_id,sequence) do nothing;
select cp.id,5,b.id,'Computer Science and Engineering','Example branch.' from public.career_paths cp cross join public.branches b where cp.slug='cybersecurity' and b.slug='cse'
on conflict(career_path_id,sequence) do nothing;
select cp.id,6,s.id,'Cybersecurity','Example specialization; availability is institution-specific.' from public.career_paths cp cross join public.specializations s where cp.slug='cybersecurity' and s.slug='cybersecurity'
on conflict(career_path_id,sequence) do nothing;

values ('security-analyst','Security analyst','Example role category; responsibilities and qualifications vary by employer.')
on conflict(slug) do nothing;
select cp.id,cr.id from public.career_paths cp cross join public.career_roles cr where cp.slug='cybersecurity' and cr.slug='security-analyst'
on conflict do nothing;

select cp.id,s.sequence,s.title,s.description from public.career_paths cp cross join (values
  (1,'Year 1 · Foundations','Suggested beginner foundations; adapt to your institution syllabus.'),
  (2,'Year 2 · Core skills','Suggested computing foundations before specialist study.'),
  (3,'Year 3 · Specialization','Illustrative security concepts for guided learning.'),
  (4,'Year 4 · Practice','Illustrative advanced practice and project work.')
) as s(sequence,title,description) where cp.slug='cybersecurity'
on conflict(career_path_id,sequence) do nothing;

select rs.id,s.id,sk.sequence from public.roadmap_stages rs cross join (values
  (1,'programming-fundamentals'),(1,'communication'),(2,'networking-fundamentals'),(2,'linux-basics'),
  (3,'security-fundamentals'),(3,'web-security'),(4,'cloud-security')
) as sk(sequence,slug) join public.skills s on s.slug=sk.slug
where rs.career_path_id=(select id from public.career_paths where slug='cybersecurity') and rs.sequence=sk.sequence
on conflict do nothing;

on conflict(slug) do nothing;
select p.id,s.id from public.projects p cross join public.skills s where
  (p.slug='security-learning-notes' and s.slug in ('security-fundamentals','communication')) or
  (p.slug='network-map' and s.slug='networking-fundamentals') or
  (p.slug='security-capstone' and s.slug in ('security-fundamentals','cloud-security'))
on conflict do nothing;
select cp.id,p.id,rs.id from public.career_paths cp cross join public.projects p left join public.roadmap_stages rs on rs.career_path_id=cp.id and rs.sequence=case p.slug when 'security-learning-notes' then 1 when 'network-map' then 2 else 4 end
where cp.slug='cybersecurity' and p.slug in ('security-learning-notes','network-map','security-capstone')
on conflict do nothing;




-- Broad discovery starters. Records remain draft because linked directories are general references, not item-specific eligibility verification.
on conflict(slug) do nothing;

commit;
